import { pgTable, text, timestamp, uuid } from 'drizzle-orm/pg-core';

/*
 * Conventions (see Notion → Data model):
 * - IDs are UUID v7 (generated by the app or by devices)
 * - Money columns are bigint millimes: bigint(name, { mode: 'number' })
 * - Every business table carries tenant_id and/or branch_id
 * - snake_case columns, plural table names
 */

const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp('updated_at', { withTimezone: true }).notNull().defaultNow();

/** A business using the SaaS (one owner account, one or many branches). */
export const tenants = pgTable('tenants', {
  id: uuid('id').primaryKey(),
  name: text('name').notNull(),
  /** Matricule fiscal, printed on receipts and factures. */
  taxId: text('tax_id'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/** One physical location: a café, a restaurant, a shop. */
export const branches = pgTable('branches', {
  id: uuid('id').primaryKey(),
  tenantId: uuid('tenant_id')
    .notNull()
    .references(() => tenants.id),
  name: text('name').notNull(),
  type: text('type', { enum: ['cafe', 'restaurant', 'retail'] }).notNull().default('cafe'),
  address: text('address'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});
